  grid_led(3, 2, _wake_pixel(2, 1))
  grid_led(4, 2, _wake_pixel(3, 1))
  grid_led(1, 3, _wake_pixel(0, 2))
  grid_led(2, 3, _wake_pixel(1, 2))
  grid_led(3, 3, _wake_pixel(2, 2))
  grid_led(4, 3, _wake_pixel(3, 2))
  grid_led(1, 4, _wake_pixel(0, 3))
  grid_led(2, 4, _wake_pixel(1, 3))
  grid_led(3, 4, _wake_pixel(2, 3))
  grid_led(4, 4, _wake_pixel(3, 3))
  grid_refresh()
end

